# ---------------------------------------------------------------
# Shared building blocks for all database tables (ORM models).
#
# DSQL-friendly choices used everywhere:
#   - UUID primary keys generated by the database (gen_random_uuid)
#   - created_at / updated_at maintained by the APP, because DSQL
#     has no triggers
# ---------------------------------------------------------------
import uuid
from datetime import datetime

from sqlalchemy import Boolean, DateTime, Integer, String, Uuid, func, text
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column


class Base(DeclarativeBase):
    """Parent of every model; Alembic reads Base.metadata."""


class TimestampMixin:
    """Adds created_at and updated_at columns."""

    # Set by the database when the row is inserted.
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now(), nullable=False
    )
    # Set on insert, and refreshed by SQLAlchemy on every UPDATE.
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now(), onupdate=func.now(), nullable=False
    )


class UuidPkMixin:
    """Adds an "id" UUID primary key generated by the database."""

    id: Mapped[uuid.UUID] = mapped_column(
        Uuid, primary_key=True, server_default=text("gen_random_uuid()")
    )


class LookupMixin(UuidPkMixin, TimestampMixin):
    """
    Common shape of a simple master-data list (stock type, unit, ...):
      code       short unique key, e.g. "WHEAT" (never shown to users)
      name       display name, e.g. "Wheat"
      sort_order controls the order in dropdowns (lower first)
      is_active  false = hidden from dropdowns but kept for old records
    """

    code: Mapped[str] = mapped_column(String(20), nullable=False, unique=True)
    name: Mapped[str] = mapped_column(String(100), nullable=False)
    sort_order: Mapped[int] = mapped_column(Integer, nullable=False, server_default="0")
    is_active: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default="true")
